#include "scheduler.hpp"
#include "fods.hpp"
#include <algorithm>
#include <cmath>
#include <numeric>
void Scheduler::submit(Job j){j.id="J"+std::to_string(nextId_++);j.status=JobStatus::Queued;j.message="Waiting for an eligible compute node";j.claimed=false;jobs_.push_back(j);}
Node* Scheduler::chooseNode(Cluster&c,const Job&j,const std::string&strategy,bool liveOnly){std::vector<Node*>e;for(auto&n:c.nodes())if(n.status!=NodeStatus::Offline&&(!liveOnly||n.live)&&(!liveOnly||j.gpuRequiredGB<=0)&&n.cpuCores>=j.cpuRequired&&(n.ramGB-n.ramUsedGB)>=j.ramRequiredGB&&(n.gpuMemoryGB-n.gpuUsedGB)>=j.gpuRequiredGB)e.push_back(&n);if(e.empty())return nullptr;
 if(strategy=="FCFS") return e.front();
 if(strategy=="Priority") return *std::min_element(e.begin(),e.end(),[](Node*a,Node*b){return a->cpuUsedPct<b->cpuUsedPct;});
 auto score=[&](Node*n){double cfree=std::max(0.0,100-n->cpuUsedPct)/100.0;double rfree=(n->ramGB-n->ramUsedGB)/n->ramGB;double gfree=n->gpuMemoryGB>0?(n->gpuMemoryGB-n->gpuUsedGB)/n->gpuMemoryGB:(j.gpuRequiredGB==0?1.0:0.0);double cfit=std::min(1.0,(n->cpuCores-j.cpuRequired+1.0)/std::max(1,n->cpuCores));double rfit=std::min(1.0,(n->ramGB-n->ramUsedGB)/std::max(.1,j.ramRequiredGB));return .30*cfree+.30*rfree+.20*gfree+.10*cfit+.10*rfit;};return *std::max_element(e.begin(),e.end(),[&](Node*a,Node*b){return score(a)<score(b);});}
void Scheduler::schedule(Cluster&c,const std::string&strategy,const std::string&mode){FODSQueue<Job*>q;FODSPriorityQueue<Job*>pq;for(auto&j:jobs_)if(j.status==JobStatus::Queued){if(strategy=="Priority")pq.push(&j,static_cast<int>(j.priority));else q.push(&j);}while(strategy=="Priority"?!pq.empty():!q.empty()){Job*j=strategy=="Priority"?pq.pop():q.pop();Node*n=chooseNode(c,*j,strategy,mode=="Live");if(!n){j->message=mode=="Live"?(j->gpuRequiredGB>0?"Queued: this build supports CPU worker execution only; GPU execution is not enabled":"Queued: waiting for a connected worker with sufficient CPU/RAM resources") : "Queued: no virtual node satisfies resource requirements";continue;}j->assignedNode=n->id;j->claimed=false;j->waitingSeconds=0;n->status=NodeStatus::Busy;n->activeJob=j->id;n->cpuUsedPct=std::min(100.0,n->cpuUsedPct+100.0*j->cpuRequired/std::max(1,n->cpuCores));n->ramUsedGB+=j->ramRequiredGB;n->gpuUsedGB+=j->gpuRequiredGB;
 if(mode=="Live"){j->status=JobStatus::Running;j->message="Assigned to live worker; awaiting agent claim";}else{j->status=JobStatus::Completed;j->executionSeconds=0;j->message="Completed in manual simulation on "+n->name;n->completedJobs++;n->status=NodeStatus::Idle;n->activeJob.clear();n->cpuUsedPct=std::min(95.0,std::max(n->cpuUsedPct*0.72,12.0+((j->cpuRequired*11)%55)));n->ramUsedGB=std::max(0.0,n->ramUsedGB-j->ramRequiredGB);n->gpuUsedGB=std::max(0.0,n->gpuUsedGB-j->gpuRequiredGB);}}
}
Job* Scheduler::nextForWorker(const std::string&nodeId){for(auto&j:jobs_)if(j.status==JobStatus::Running&&j.assignedNode==nodeId&&!j.claimed){j.claimed=true;j.message="Worker agent is executing approved workload";return &j;}return nullptr;}
void Scheduler::release(Job&j,Cluster&c){Node*n=c.findNode(j.assignedNode);if(!n)return;n->cpuUsedPct=std::max(0.0,n->cpuUsedPct-100.0*j.cpuRequired/std::max(1,n->cpuCores));n->ramUsedGB=std::max(0.0,n->ramUsedGB-j.ramRequiredGB);n->gpuUsedGB=std::max(0.0,n->gpuUsedGB-j.gpuRequiredGB);n->activeJob.clear();if(n->status!=NodeStatus::Offline)n->status=NodeStatus::Idle;}
bool Scheduler::completeRemote(const std::string&jid,const std::string&nid,bool success,const std::string&result,double seconds,Cluster&c){for(auto&j:jobs_)if(j.id==jid&&j.assignedNode==nid&&j.status==JobStatus::Running){release(j,c);j.executionSeconds=std::max(0.0,seconds);j.result=result;j.status=success?JobStatus::Completed:JobStatus::Failed;j.message=success?"Completed by connected worker":"Worker reported workload failure";if(success){if(Node*n=c.findNode(nid))n->completedJobs++;}return true;}return false;}
void Scheduler::recoverNode(const std::string&id,Cluster&c,const std::string&strategy){for(auto&j:jobs_)if(j.assignedNode==id&&j.status==JobStatus::Running){j.status=JobStatus::Queued;j.claimed=false;j.assignedNode.clear();j.message="Requeued after worker disconnect; workload will restart from beginning";}if(Node*n=c.findNode(id)){n->cpuUsedPct=0;n->ramUsedGB=0;n->gpuUsedGB=0;n->activeJob.clear();n->claimed=false;}c.failNode(id);schedule(c,strategy,"Live");}
Metrics Scheduler::metrics(const Cluster&c)const{Metrics m;m.submitted=(int)jobs_.size();double w=0,x=0,u=0;int active=0;for(const auto&j:jobs_){if(j.status==JobStatus::Completed){m.completed++;w+=j.waitingSeconds;x+=j.executionSeconds;}else if(j.status==JobStatus::Queued)m.queued++;else if(j.status==JobStatus::Running)m.running++;else m.failed++;}for(const auto&n:c.nodes())if(n.status!=NodeStatus::Offline){u+=n.cpuUsedPct;active++;}m.averageWaitingSeconds=m.completed?w/m.completed:0;m.averageExecutionSeconds=m.completed?x/m.completed:0;m.averageUtilizationPct=active?u/active:0;m.resourceWastagePct=active?100-m.averageUtilizationPct:0;return m;}
void Scheduler::reset(){jobs_.clear();nextId_=1;}
